"""Publish the visual revision without replacing the earlier experiment evidence."""
from pathlib import Path
import hashlib, json, shutil

ROOT=Path(__file__).resolve().parents[4]
HERE=Path(__file__).resolve().parent
RUN=ROOT/'ada_run/encounter_pilot/Random_Entropy/entropy-lab-form'
for name in ['report.json','bench-balanced.png','bench-separated.png','entrance-comparison.png','source_manifest.json']:
    shutil.copy2(RUN/name,HERE/('museum-report.json' if name=='report.json' else name))
reports=[json.loads(p.read_text(encoding='utf8')) for p in [HERE/'verification.json',HERE/'reconstruction/verification.json',HERE/'museum-report.json']]
assert all(r['passed'] for r in reports)
model=ROOT/'commons/artifacts/entropy_compartments/compartment_model.gd'
assert model.read_bytes()==(HERE/'before/commons/artifacts/entropy_compartments/compartment_model.gd').read_bytes()
paths=[* (ROOT/'commons/artifacts/entropy_compartments').glob('*.gd'),* (ROOT/'commons/artifacts/entropy_compartments').glob('*.tscn'),ROOT/'commons/artifacts/registry/randomness.json',ROOT/'commons/maps/Random_Entropy/tutorial.md',ROOT/'commons/maps/Random_Entropy/final.md']
(HERE/'manifest.json').write_text(json.dumps({'model_unchanged':True,'checks':[len(r['checks']) for r in reports],'sha256':{p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}},indent=2),encoding='utf8')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entropy — the laboratory form</title><style>
*{box-sizing:border-box}body{margin:0;background:#101e27;color:#e3eceb;font:17px/1.6 system-ui}main{max-width:1550px;padding:28px;margin:auto}h1{font-size:40px;line-height:1.15;margin:20px 0}h2{font-size:24px}a{color:#80d7df}nav{display:flex;flex-wrap:wrap;gap:20px;font-size:14px}.intro{max-width:1000px}.spread{display:grid;grid-template-columns:1fr 1fr;gap:20px}figure{margin:0}img{width:100%;height:auto;border:1px solid #39535f}figcaption,.small{font-size:14px;color:#b8ccc9}.choice{display:inline-block;font:16px system-ui;padding:12px 22px;border:1px solid #6b9399;background:#233b48;color:#fff;cursor:pointer;margin:8px 5px 20px 0}#balanced:checked+label,#separated:checked+label{background:#3c6167;border-color:#89dae0}input[type=radio]{position:absolute;left:-9999px}input:focus-visible+label{outline:3px solid white}.separated-image{display:none}#separated:checked~.spread .separated-image{display:block}#separated:checked~.spread .balanced-image{display:none}.note{border-left:3px solid #d6a25e;padding-left:18px}code{font-size:14px}@media(max-width:850px){.spread{grid-template-columns:1fr}h1{font-size:30px}main{padding:18px}}</style>
<main><nav><a href="/long-museum/writing-wall?map=Random_Entropy">Random Entropy writing wall</a><a href="/surreal-lab-gallery">Visual reference</a><a href="README.md">Changes and evidence</a><a href="/book-review/commons/maps/Random_Entropy/tutorial.md">Tutorial</a><a href="/book-review/commons/maps/Random_Entropy/final.md">Final</a></nav>
<div class="intro"><p class="small">ADA RESEARCH · RANDOM ENTROPY · 15 OCTOBER 2026</p><h1>Two accounts, one laboratory instrument</h1><p>Glass-sided specimen trays, luminous occupants and two round dials on a dark steel cabinet. The same sixteen sites remain underneath the new form.</p><p>The cyan dial measures colour shares in bits. The amber dial measures configurational entropy divided by k_B. Moving an A across changes the second reading while the first remains fixed.</p></div>
<input type="radio" id="balanced" name="arrangement" checked><label class="choice" for="balanced">Four A on each side</label><input type="radio" id="separated" name="arrangement"><label class="choice" for="separated">Separated baseline</label>
<div class="spread"><figure><h2>Earlier bench</h2><img class="balanced-image" src="before-bench-balanced.png" alt="Earlier bench, four A per side"><img class="separated-image" src="before-bench-separated.png" alt="Earlier bench, separated baseline"><figcaption>Earlier native hall capture.</figcaption></figure><figure><h2>Laboratory form</h2><img class="balanced-image" src="bench-balanced.png" alt="Laboratory instrument, four A per side"><img class="separated-image" src="bench-separated.png" alt="Laboratory instrument, separated baseline"><figcaption>Current native hall capture. The camera is pulled back slightly for the taller dials.</figcaption></figure></div>
<div class="spread"><section><h2>What changes with the arrangement?</h2><p>In the separated baseline, H = 1 bit, Ω = 1 and S_B/k_B = 0. With four A on each side, H stays at 1, Ω = 4,900 and S_B/k_B ≈ 8.497. The amber pointer and bar follow that measured change. SAME k can move the occupants while both readings stay.</p><p class="note">These buttons compare captured images. For the live experiment, run <code>commons/artifacts/entropy_compartments/preview.tscn</code> in Godot with F6, or revisit Random Entropy in the museum.</p></section><section><h2>The experiment survives its new form</h2><p>The model, seeded swaps and saved-record format are unchanged. The tutorial and final now describe the glass trays and dials. The hall position, walking sequence and text order stay in place.</p><p><a href="verification.json">55 apparatus checks</a> · <a href="reconstruction/verification.json">55 reconstruction checks</a> · <a href="museum-report.json">16 hall checks</a> passed. Headset comfort and Quest performance still need a physical trial.</p><p>Also completed: <a href="../2026-10-15-rhino-random-structures/index.html">four random structure studies from the Rhino scripts</a>.</p></section></div></main>
</html>'''
(HERE/'index.html').write_text(page,encoding='utf8')
print('Published',HERE/'index.html')
